import React, { type FC } from 'react';
import type { L1IconType } from '../types';

interface L1IconProps extends L1IconType {
  visual: FC<L1IconType>;
}

const L1Icon = ({ visual: Icon, size = 'sm', color = 'currentColor' }: L1IconProps) => (
  <Icon size={size} color={color} />
);

export default L1Icon;
