import React from 'react';
import * as icons from '..';
import type { L1IconType } from '../../types';

interface L1IconTypeDemo extends L1IconType {
  iconName: keyof typeof icons;
}

const Demo = ({ size = 'sm', iconName, color = 'currentColor' }: L1IconTypeDemo) => {
  const Icon = icons[iconName];
  return <Icon color={color} size={size} />;
};

export default Demo;
